#### Expected Behavior
Do not try to fill an order with the same data.

#### Actual Behavior
1- For a single algorithm manager loop, the backtesting brokerage is triggered immediately for each order, and in the case of Market orders he fills immediately too. Also the backtesting brokerage is triggered at the end of each loop.
2- Once the backtesting brokerage gets an Order he creates a copy. So in the case of a partial fill the orders won't be updated, for example `LastFillTime`. Note that this is the Order which gets sent to the fill models. Since `LastFillTime` isn't sent, it can't use this information to decide whether it should emit a new partial fill + `1-` produces two fills per loop unless the fill model keeps track himself of the last fill time.

#### Reproducing the Problem
```csharp
namespace QuantConnect.Algorithm.CSharp {
    public class CustomModelsAlgorithm : QCAlgorithm {
        private Security _security;
        private Symbol _spy;

        public override void Initialize() {
            SetStartDate(2013, 10, 01);
            SetEndDate(2013, 10, 31);
            _security = AddEquity("SPY", Resolution.Hour);
            _spy = _security.Symbol;
            _security.SetFillModel(new CustomFillModel(this));
        }

        public void OnData(TradeBars data) {
            var openOrders = Transactions.GetOpenOrders(_spy);
            if (openOrders.Count != 0) return;

            if (Time.Day > 10 && _security.Holdings.Quantity <= 0) {
                var quantity = CalculateOrderQuantity(_spy, .5m);
                MarketOrder(_spy, quantity, asynchronous: true); // async needed for partial fill market orders
            } else if (Time.Day > 20 && _security.Holdings.Quantity >= 0) {
                var quantity = CalculateOrderQuantity(_spy, -.5m);
                MarketOrder(_spy, quantity, asynchronous: true); // async needed for partial fill market orders
            }
        }

        public class CustomFillModel : ImmediateFillModel {
            private readonly QCAlgorithm _algorithm;
            private readonly Dictionary<long, decimal> _absoluteRemainingByOrderId = new Dictionary<long, decimal>();

            public CustomFillModel(QCAlgorithm algorithm) {
                _algorithm = algorithm;
            }

            public override OrderEvent MarketFill(Security asset, MarketOrder order) {
                decimal absoluteRemaining;
                if (!_absoluteRemainingByOrderId.TryGetValue(order.Id, out absoluteRemaining)) {
                    absoluteRemaining = order.AbsoluteQuantity;
                    _absoluteRemainingByOrderId.Add(order.Id, order.AbsoluteQuantity);
                }

                var absoluteFillQuantity = (int) (Math.Min(absoluteRemaining, 100));
                fill.FillQuantity = Math.Sign(order.Quantity) * absoluteFillQuantity;

                if (absoluteRemaining == absoluteFillQuantity) {
                    fill.Status = OrderStatus.Filled;
                    _absoluteRemainingByOrderId.Remove(order.Id);
                } else {
                    absoluteRemaining -= absoluteFillQuantity;
                    _absoluteRemainingByOrderId[order.Id] = absoluteRemaining;
                    fill.Status = OrderStatus.PartiallyFilled;
                }
                _algorithm.Log("CustomFillModel: " + fill);
                return fill;
            }
        }
    }
}
```
